import { createWalletClient, custom, getAddress } from "viem";
import { toMetaMaskSmartAccount } from "@metamask/delegation-toolkit";
import { monadTestnet } from "viem/chains";

export async function initToolkit() {
  try {
    if (!window.ethereum) {
      throw new Error("MetaMask not found");
    }

    await window.ethereum.request({ method: "eth_requestAccounts" });

    console.log("monadTestnet (import):", monadTestnet);

    const [account] = await window.ethereum.request({ method: "eth_accounts" });
    const address = getAddress(account);
    console.log("Connected address:", address);

    const chainIdHex = await window.ethereum.request({ method: "eth_chainId" });
    const chainId = parseInt(chainIdHex, 16);
    console.log("MetaMask chainId:", chainId, "hex:", chainIdHex);

    const chainObj = monadTestnet ?? {
      id: chainId,
      name: "monad-testnet",
      rpcUrls: { default: { http: ["https://testnet-rpc.monad.xyz"] } }, // add a valid RPC URL if you have one
    };
    console.log("Using chain object:", chainObj);

    const walletClient = createWalletClient({
      account: address,
      chain: chainObj,
      transport: custom(window.ethereum),
    });
    console.log("viem walletClient keys:", Object.keys(walletClient));
    console.log("walletClient.chain (before):", walletClient.chain);
    console.log(
      "walletClient.transport?.request:",
      typeof walletClient.transport?.request);

    if (!walletClient.chain) {
      try {
        walletClient.chain = chainObj;
        console.log("Attached chainObj to walletClient.chain");
      } catch (e) {
        console.warn("Failed to attach chainObj to walletClient:", e);
      }
    }

    console.log("signer (walletClient) keys:", Object.keys(walletClient));
    console.log("walletClient.chain:", walletClient.chain);
    try {
      console.log(
        "toMetaMaskSmartAccount source (snippet):",
        toMetaMaskSmartAccount.toString().slice(0, 800)
      );
    } catch (e) {
      console.warn("could not stringify toMetaMaskSmartAccount", e);
    }
    let smartAccount;
    try {
      smartAccount = await toMetaMaskSmartAccount({
        client: walletClient,
        signer: { walletClient },
        chain: chainObj, // ✅ explicitly use viem chain here
      });

      console.log("✅ Smart account created:", smartAccount);
    } catch (err) {
      console.error("toMetaMaskSmartAccount threw:", err);
      throw err;
    }

    // Return toolkit-like interface
    return {
      connect: async () => smartAccount,
      getSmartAccountAddress: async () => address,
    };
  } catch (err) {
    console.error("❌ Smart Account connection failed:", err);
    return null;
  }
}
